def main_solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1"

    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    roads = []
    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        roads.append((u, v, w, i + 1))

    adj = [[] for _ in range(n + 1)]
    for i, (u, v, w, idx) in enumerate(roads):
        adj[u].append((v, i))
        adj[v].append((u, i))

    def check_paths(edges_blocked: Set[int]) -> bool:
        q = deque([(s, 0)])
        visited = {s}
        while q:
            curr, _ = q.popleft()
            if curr == t:
                return True
            for neighbor, edge_idx in adj[curr]:
                if edge_idx not in edges_blocked and neighbor not in visited:
                    visited.add(neighbor)
                    q.append((neighbor, edge_idx))
        return False

    if not check_paths(set()):
        return "0\n0\n"

    best = float('inf')
    ans = None

    # One edge
    for i, (u, v, w, idx) in enumerate(roads):
        if not check_paths({i}):
            if w < best:
                best = w
                ans = (w, 1, [idx])

    if ans:
        return f"{ans[0]}\n{ans[1]}\n{' '.join(map(str, ans[2]))}\n"

    # Two edges
    for i, (u1, v1, w1, idx1) in enumerate(roads):
        if best <= w1:
            continue
        if not check_paths({i}):
            continue
        for j, (u2, v2, w2, idx2) in enumerate(roads):
            if i >= j or w1 + w2 >= best:
                continue
            if not check_paths({i, j}):
                if w1 + w2 < best:
                    best = w1 + w2
                    ans = (best, 2, [idx1, idx2])

    if ans:
        return f"{ans[0]}\n{ans[1]}\n{' '.join(map(str, ans[2]))}\n"

    return "-1"

def solution(input_str: str) -> str:
