        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px != py:
            self.parent[px] = py
            if self.length[px] < self.length[py]:
                px, py = py, px
            self.length[py] += self.length[px]

    def is_range_free(self, l, r):
        """Check if all days in range [l, r] are not in any accepted offer group"""
        # We'll track the next free day after the last occupied
        return r - l + 1 == r - self.next_free[l] + 1

    def solve(self, x):
        occupied_next = [0] * (self.n + 2)
