    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Read edges
    edges = []
    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        edges.append((w, u, v, i))

    # Sort for Kruskal's
    edges_sorted = sorted(edges)

    # Build MST
    dsu = DSU(n)
    mst_set = set()

    for w, u, v, i in edges_sorted:
        if dsu.union(u, v):
            mst_set.add(i)

    # Build MST adjacency list
    adj = [[] for _ in range(n + 1)]
    for w, u, v, i in edges:
        if i in mst_set:
            adj[u].append((v, w))
            adj[v].append((u, w))

    # Binary lifting preprocessing
    LOG = n.bit_length() + 1
    up = [[-1] * LOG for _ in range(n + 1)]
    max_path = [[0] * LOG for _ in range(n + 1)]
    depth = [0] * (n + 1)

    # DFS from root (vertex 1)
    stack = [(1, -1, 0, 0)]  # node, parent, depth, max_edge_from_parent

    while stack:
        u, p, d, w = stack.pop()
        depth[u] = d
        up[u][0] = p
        max_path[u][0] = w

        for i in range(1, LOG):
            if up[u][i-1] != -1:
                up[u][i] = up[up[u][i-1]][i-1]
                max_path[u][i] = max(max_path[u][i-1], max_path[up[u][i-1]][i-1])

        for v, e in adj[u]:
            if v != p:
                stack.append((v, u, d + 1, e))

    # Query max edge on path between u and v
    def query_max_path(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        res = 0
        # Lift u to same depth as v
        diff = depth[u] - depth[v]
        for i in range(LOG):
            if diff & (1 << i):
                res = max(res, max_path[u][i])
                u = up[u][i]

        if u == v:
            return res

        # Lift both until just below LCA
        for i in range(LOG - 1, -1, -1):
            if up[u][i] != up[v][i]:
                res = max(res, max_path[u][i])
                res = max(res, max_path[v][i])
                u = up[u][i]
                v = up[v][i]

        # Final step to LCA
        res = max(res, max_path[u][0])
        res = max(res, max_path[v][0])
        return res

    # Collect results for non-MST edges
    res = []
    for w, u, v, i in edges:
        if i not in mst_set:
            mx = query_max_path(u, v)
            res.append(str(mx - 1))

    return '\n'.join(res)

