class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [0] * (4 * self.n)
        self.lazy = [0] * (4 * self.n)
        self._build(arr, 1, 0, self.n - 1)

    def _build(self, arr, node, start, end):
        if start == end:
            self.tree[node] = arr[start]
        else:
            mid = (start + end) // 2
            self._build(arr, 2*node, start, mid)
            self._build(arr, 2*node+1, mid+1, end)
            self.tree[node] = max(self.tree[2*node], self.tree[2*node+1])

    def push(self, node, start, end):
        if self.lazy[node] != 0:
            mid = (start + end) // 2
            self.tree[2*node] += self.lazy[node]
            self.lazy[2*node] += self.lazy[node]
            self.tree[2*node+1] += self.lazy[node]
            self.lazy[2*node+1] += self.lazy[node]
            self.lazy[node] = 0

    def _update_range(self, node, start, end, l, r, val):
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.tree[node] += val
            self.lazy[node] += val
            return
        self.push(node, start, end)
        mid = (start + end) // 2
        self._update_range(2*node, start, mid, l, r, val)
        self._update_range(2*node+1, mid+1, end, l, r, val)
        self.tree[node] = max(self.tree[2*node], self.tree[2*node+1])

    def range_add(self, l, r, val):
        self._update_range(1, 0, self.n - 1, l, r, val)

    def _query_max(self, node, start, end, l, r):
        if r < start or end < l:
            return -float('inf')
        if l <= start and end <= r:
            return self.tree[node]
        self.push(node, start, end)
        mid = (start + end) // 2
        left_max = self._query_max(2*node, start, mid, l, r)
        right_max = self._query_max(2*node+1, mid+1, end, l, r)
        return max(left_max, right_max)

    def query_max(self, l, r):
        return self._query_max(1, 0, self.n - 1, l, r)

