def solution(s):
    # Parse the input
    lines = s.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Memoization for Grundy numbers
    memo = {}

    def grundy(n):
        """Compute Grundy number for a pile of size n"""
        if n in memo:
            return memo[n]

        # Possible moves: remove 1 cow -> state n-1
        reachable = {grundy(n - 1)}

        # If even, can split into k piles of size n/2
        if n % 2 == 0:
            x = n // 2
            if k % 2 == 1:
                # k is odd, XOR of k copies of g(x) is just g(x)
                reachable.add(grundy(x))
            else:
                # k is even, XOR of k copies of g(x) is 0
                reachable.add(0)

        # Compute mex
        g = 0
        while g in reachable:
            g += 1

        memo[n] = g
        return g

    # XOR sum of all piles
    xor_sum = 0
    for x in a:
        xor_sum ^= grundy(x)

    # If XOR sum is non-zero, first player (Kevin) wins
    if xor_sum != 0:
        return "Kevin\n"
    else:
        return "Nicky\n"


