def solution(input_str):
    import sys
    from collections import deque

    data = input_str.strip().split('\n')
    n, m = map(int, data[0].split())

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, data[i].split())
        graph[u].append(v)
        graph[v].append(u)

    # Find connected components and their sizes
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = deque([i])
            visited[i] = True
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(size)

    # Generate all lucky numbers up to n
    lucky_numbers = set()
    def generate_lucky(current):
        if current > n:
            return
        if current != 0:
            lucky_numbers.add(current)
        generate_lucky(current * 10 + 4)
        generate_lucky(current * 10 + 7)
    generate_lucky(0)
    lucky_list = sorted(lucky_numbers)

    # Check if any component is already lucky
    for size in components:
        if size in lucky_numbers:
            return '0'

    total_sum = sum(components)

    # Check if total is already lucky (all merged)
    if total_sum in lucky_numbers:
        return str(n - sum(1 for _ in components) - 1 if len(components) > 1 else 0)

    # Try to find minimum roads to merge components to form a lucky number
    min_roads = float('inf')

    # DP to check subset sum with minimum count
    INF = n + 1
    dp = [INF] * (max(lucky_list) + 1)
    dp[0] = 0

    for size in components:
        for s in range(max(lucky_list), size - 1, -1):
            if dp[s - size] != INF:
                dp[s] = min(dp[s], dp[s - size] + 1)

    for target in lucky_list:
        if dp[target] != INF:
            min_roads = min(min_roads, dp[target] - 1)

    return str(min_roads) if min_roads != float('inf') else '-1'

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    def is_gp(seq):
        """Check if a sequence is a geometric progression."""
        if len(seq) <= 2:
            return True

        all_zero = all(x == 0 for x in seq)
        if all_zero:
            return True

        first = -1
        for i in range(len(seq)):
            if seq[i] != 0:
                first = i
                break

        if first == -1:
            return True

        if seq[first] == 0:
            return True

        second = -1
        for i in range(first + 1, len(seq)):
            if seq[i] != 0:
                second = i
                break

        if second == -1:
            return True

        if seq[second] == 0:
            for k in range(second + 1, len(seq)):
                if seq[k] != 0:
                    return False
            return True

        ratio_num = seq[second]
        ratio_den = seq[first]

        for k in range(second + 1, len(seq)):
            prev = seq[k-1]
            curr = seq[k]
            if prev == 0:
                continue
            if ratio_num * prev != ratio_den * curr:
                return False

        return True

    if is_gp(arr):
        return '0\n'

    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return '1\n'

    return '2\n'

