def kmp_preprocess(pattern):
    """Build KMP failure function (pi array)"""
    m = len(pattern)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and pattern[i] != pattern[j]:
            j = pi[j-1]
        if pattern[i] == pattern[j]:
            j += 1
        pi[i] = j
    return pi

def kmp_count(text, pattern):
    """Count occurrences of pattern in text using KMP"""
    if len(pattern) > len(text) or len(pattern) == 0:
        return 0
    pi = kmp_preprocess(pattern)
    text_str = str(text)
    count = 0
    j = 0
    m = len(pattern)
    n_ = len(text_str)
    for i in range(n_):
        while j > 0 and text_str[i] != pattern[j]:
            j = pi[j-1]
        if text_str[i] == pattern[j]:
            j += 1
        if j == m:
            count += 1
            j = pi[j-1]
    return count

