    prefix_dist = [0] * (n + 1)
    for i in range(n):
        prefix_dist[i + 1] = prefix_dist[i] + d[i]

    total_dist = prefix_dist[n]

    def clockwise_dist(a, b):
        """Distance from tree a to b going clockwise (0-indexed)"""
        if a == b:
            return 0
        if a < b:
            return prefix_dist[b] - prefix_dist[a]
        else:
            return total_dist - (prefix_dist[a] - prefix_dist[b])

    def ccw_dist(a, b):
        """Distance from tree a to b going counterclockwise (0-indexed)"""
        if a == b:
            return 0
        if a < b:
            return total_dist - (prefix_dist[b] - prefix_dist[a])
        else:
            return prefix_dist[a] - prefix_dist[b]

    def min_dist(a, b, blocked_start, blocked_end, total):
        """Compute shortest valid distance between a and b (0-indexed) that doesn't pass through blocked range"""
        cw = clockwise_dist(a, b)
        ccw = ccw_dist(a, b)

        blocked_len = (blocked_end - blocked_start + total) % total

        # Check if clockwise path goes through blocked range
        # Path through blocked if either:
        # - Start is in blocked and end is after it in clockwise, or
        # - End is in blocked and start is before it in clockwise, or
        # - The arc traverses across blocked_start to blocked_end

        def covers_clockwise(start, end):
            """Returns True if clockwise path from start to end covers the blocked range"""
            if start <= end:
                return start <= blocked_start and blocked_end <= end
            else:
                return blocked_start <= start <= blocked_end or blocked_start <= end <= blocked_end

        def covers_ccw(start, end):
            """Returns True if counterclockwise path from start to end covers the blocked range"""
            if start <= end:
                return blocked_start <= start or end <= blocked_end
            else:
                return start <= blocked_start or blocked_end <= end

        def in_blocked(idx):
            """Check if index is in blocked range"""
            if blocked_start <= blocked_end:
                return blocked_start <= idx <= blocked_end
            else:
                return idx >= blocked_start or idx <= blocked_end

        # Both paths may or may not go through blocked, need smart computation
        # Try both and pick the one that doesn't go through blocked
        if in_blocked(a) or in_blocked(b):
            raise ValueError(f"Can't choose tree in blocked: {a}, {b} in [{blocked_start}, {blocked_end}]")

        return min(cw, ccw)

    results = []

    for _ in range(m):
        line = lines[3 + len(results)]
        a, b = map(int, line.split())

        # Convert to 0-indexed
        a0, b0 = a - 1, b - 1

        # Find blocked range
        if a0 <= b0:
            blocked_start, blocked_end = a0, b0
        else:
            blocked_start, blocked_end = a0, n - 1 if b0 >= 0 else -1
            # Actually circular: [a0, n) U [0, b0]
            # Use a normalized range representation
            blocked_start, blocked_end = (a0, n - 1) if a0 <= n - 1 else (a0, b0 - 1 + 1)

        # Market simulation logic for blocked range
        if a0 <= b0:
            blocked_start, blocked_end = a0, b0
        elif n == 1:
            blocked_start, blocked_end = a0, a0
        elif a0 < n - 1 and b0 == n - 1:
            blocked_start, blocked_end = a0, n - 1
        else:
            blocked_start, blocked_end = a0, b0

        valid_trees = []
        for i in range(n):
            if i == a - 1:
                continue
            if i == b - 1:
                continue
            valid_trees.append(i)

        max_energy = 0
        num_valid = len(valid_trees)

        for i in range(num_valid):
