def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def on_segment(p, a, b):
    if cross(a, b, p) != 0:
        return False
    return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

def on_edge(tri, p):
    for i in range(3):
        a = tri[i]
        b = tri[(i + 1) % 3]
        if on_segment(p, a, b):
            return True
    return False

def triangle_disjoint(tr1, tr2):
    # No shared vertices
    for p in tr2:
        if p in tr1:
            return False

    # No point of t2 is inside or on boundary of t1
    for p in tr2:
        if on_edge(tr1, p) or cross(tr1[0], tr1[1], p) == 0 and cross(tr1[1], tr1[2], p) == 0 and cross(tr1[2], tr1[0], p) == 0:
            return False
        d1 = cross(tr1[0], tr1[1], p)
        d2 = cross(tr1[1], tr1[2], p)
        d3 = cross(tr1[2], tr1[0], p)
        if (d1 >= 0 and d2 >= 0 and d3 >= 0) or (d1 <= 0 and d2 <= 0 and d3 <= 0):
            return False

    # No point of t1 is inside or on boundary of t2
    for p in tr1:
        if on_edge(tr2, p) or cross(tr2[0], tr2[1], p) == 0 and cross(tr2[1], tr2[2], p) == 0 and cross(tr2[2], tr2[0], p) == 0:
