def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return '-1'

    try:
        n, m = map(int, lines[0].split())
    except:
        return '-1'

    if n * m == 0 or n < 1 or m < 1:
        return '-1'

    total = n * m

    result = [[0] * m for _ in range(n)]

    # Place maximum at (0,0)
    result[0][0] = total

    # Fill first row decreasing from position 1
    for j in range(1, m):
        result[0][j] = total - j

    # Fill first column decreasing from position 1
    for i in range(1, n):
        result[i][0] = total - i - m + 1

    # Fill interior positions decreasing row by row
    current = total - n * m + 2
    for i in range(1, n):
        for j in range(1, m):
            result[i][j] = current
            current += 1

    # Output
    output_lines = []
    for row in result:
        output_lines.append(' '.join(map(str, row)))

    return '\n'.join(output_lines)

def solution(input_data):
    try:
        lines = input_data.strip().split('\n')
        n, k = map(int, lines[0].split())
        s = lines[1]
    except:
        return "NO\n"

    # dp[balance] = True if this balance is reachable at current position
    # balance = wins - loses
    dp = {0: True}

    # path tracks which character reached each (position, balance) state
    path = {}

    for i in range(n):
        new_dp = {}
        new_path = {}

        for balance, reachable in dp.items():
            if not reachable:
                continue

            # Determine which characters can be used
            choices = []
            if s[i] == '?':
                choices = ['W', 'L', 'D']
            else:
                choices = [s[i]]

            for char in choices:
                # Calculate new balance after this hand
                if char == 'W':
                    new_balance = balance + 1
                elif char == 'L':
                    new_balance = balance - 1
                else:  # D
                    new_balance = balance

                # Check if this state is valid
                valid = True

                if i < n - 1:
                    # Before the final hand, balance cannot equal k or -k
                    if abs(new_balance) == k:
                        valid = False
                else:
                    # After the final hand, balance must equal k or -k
                    if abs(new_balance) != k:
                        valid = False

                if valid:
                    new_dp[new_balance] = True
                    new_path[(i, new_balance)] = char

        dp = new_dp
        path = new_path

    # Check if any valid final state exists
    valid_endings = [b for b in dp if abs(b) == k]

    if not valid_endings:
        return "NO\n"

    # Reconstruct one valid solution
    result = [''] * n
    curr_balance = valid_endings[-1]  # Pick any valid ending

    for i in range(n - 1, -1, -1):
        if (i, curr_balance) not in path:
            return "NO\n"

        char_used = path[(i, curr_balance)]
        result[i] = char_used

        # Calculate previous balance
        if char_used == 'W':
            prev_balance = curr_balance - 1
        elif char_used == 'L':
            prev_balance = curr_balance + 1
        else:  # D
            prev_balance = curr_balance

        curr_balance = prev_balance

    return ''.join(result) + '\n'


